  rep, modeOrder, capMs, completionMs, observationMs: [capMs, completionMs], terminationPolicy: 'natural-completion-or-idle-stall',
  preflight, businessStageMap: { g1: 'G3', g2: 'G4' }, seedSha256, suiteIdentity, startedAt: new Date().toISOString(),
  isolation: { drive: 'G:', runner: 'run.mjs', output: basename(run), home: 'h', profile: 'h/profiles/qa',
    temp: 'tmp', pnpmStore: 'pnpm-store', wslTmpdir: linux(temp) } };
let host, server, stdout = '', stderr = '';

class ProbeInputError extends Error {
  constructor(field) {
    super('invalid recipe input');
    this.field = field;
  }
}

async function evaluateProbe(source, probe) {
  const allowed = new Set(['recipe', 'stdin', 'args', 'files', 'trace']);
  if (!probe || Object.keys(probe).some(key => !allowed.has(key)) ||
      !['engineering-python-syntax', 'engineering-json'].includes(probe.recipe)) throw Error('invalid probe scope');
  if (Object.hasOwn(probe, 'trace') && (probe.trace !== true || probe.recipe !== 'engineering-json')) {
    throw Error('invalid internal trace request');
  }
  // Report only the field name. The receipt must never echo an argv path or stdin.
  if (probe.files !== undefined && (!Array.isArray(probe.files) || probe.files.length !== 0)) throw new ProbeInputError('files');
  let target = null;
  if (probe.recipe === 'engineering-python-syntax') {
    if (!Array.isArray(probe.args) || probe.args.length !== 1 || !files.includes(probe.args[0]) ||
        !Object.hasOwn(source.bytes, probe.args[0])) throw new ProbeInputError('args');
    if (probe.stdin !== undefined) throw new ProbeInputError('stdin');
    [target] = probe.args;
  } else {
    if (probe.args !== undefined && (!Array.isArray(probe.args) || probe.args.length !== 0)) throw new ProbeInputError('args');
    if (probe.stdin !== undefined && (typeof probe.stdin !== 'string' || Buffer.byteLength(probe.stdin) > 8192)) {
      throw new ProbeInputError('stdin');
    }
  }
  // Pass data over stdin so no payload or path reaches an operating-system command interpreter.
  const args = ['-d', 'Ubuntu', '--exec', '/usr/bin/env', 'TMPDIR=' + linux(temp), 'PYTHONDONTWRITEBYTECODE=1',
    '/usr/bin/python3', '-B', linux(join(here, 'review-probe.py')), linux(source.location), linux(join(here, 'python_syntax.py')),
    linux(join(here, 'python_trace.py')), 'release.py', ...files];
  const child = spawn('wsl.exe', args, { ...context, stdio: ['pipe', 'pipe', 'ignore'] });
  const output = [];
  let size = 0;
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => { child.kill(); reject(Error('review probe timed out')); }, 12_000);
    child.stdin.on('error', reject);
    child.on('error', reject);
    child.stdout.on('data', data => {
      size += data.length;
      if (size > 16384) { child.kill(); reject(Error('review probe output too large')); }
      else output.push(data);
    });
    child.on('close', code => {
      clearTimeout(timeout);
      if (code !== 0) { reject(Error('review probe runner unavailable')); return; }
      try { resolve(JSON.parse(Buffer.concat(output))); } catch (error) { reject(error); }
    });
    child.stdin.end(JSON.stringify({ target, ...(probe.trace === true ? { trace: true } : {}),
      ...(probe.stdin !== undefined ? { stdin: probe.stdin } : {}) }));
  });
}

function createDiagnostics(caseInventory) {
  const observed = new Map();
  const preparedProbes = new Set();
  return createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/engineering-check' || req.headers.authorization !== 'Bearer ' + diagKey) {
      res.writeHead(404).end();
      return;
    }
    try {
      const chunks = [];
      let length = 0;
      for await (const chunk of req) {
        length += chunk.length;
        if (length > 2_097_152) throw Error('diagnostics payload cap');
        chunks.push(chunk);
      }
      const q = JSON.parse(Buffer.concat(chunks));
      const stage = q.checkSet === 'engineering-g1' ? 'g1' : q.checkSet === 'engineering-g2' ? 'g2' : undefined;
      const envelope = { spec: 'building-loop/diagnostics/2', requestId: q.requestId, snapshotSha256: q.snapshotSha256 };
      if (!stage || q.spec !== envelope.spec || !['check', 'probe'].includes(q.operation) || !Array.isArray(q.artifacts) ||
          JSON.stringify(q.artifacts.map(item => item.path)) !== JSON.stringify(files) || typeof q.requestId !== 'string' ||
          !/^[a-f0-9]{64}$/u.test(q.snapshotSha256)) throw Error('unexpected diagnostics contract');
      for (const ids of [q.protectedCases, q.requiredCases]) {
        if (!Array.isArray(ids) || ids.some(id => !caseInventory[stage].includes(id))) throw Error('unregistered case');
      }
      const source = Object.fromEntries(q.artifacts.filter(item => item.sha256 !== null).map(item => {
        const bytes = Buffer.from(item.contentBase64, 'base64');
        if (digest(bytes) !== item.sha256) throw Error('diagnostics artifact integrity');
        return [item.path, bytes];
      }));
      const hash = fingerprint(source);
      const slot = stage + '-' + hash;
      const location = join(run, 'diag', slot);
      if (q.operation === 'probe') {
        const probeLocation = join(run, 'review-probe', slot);
        // Concurrent shape probes share the snapshot without rewriting bytes
        // under a running WSL reader.
        if (!preparedProbes.has(slot)) {
          materialize(probeLocation, source);
          preparedProbes.add(slot);
        }
        let probe;
        try { probe = await evaluateProbe({ location: probeLocation, bytes: source }, q.probe); }
        catch (error) {
          const failure = error instanceof ProbeInputError
            ? { status: 'invalid-input', inputError: error.field }
            : { status: 'unavailable' };
          res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({ ...envelope, ...failure }));
          return;
        }
        const result = ['unavailable', 'execution-timeout'].includes(probe.status) && Object.keys(probe).length === 1
          ? { status: probe.status }
          : { status: probe.exitCode === 0 ? 'passed' : 'failed', probe };
        res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({ ...envelope, ...result }));
        return;
      }
      if (!observed.has(slot)) {
        materialize(location, source);
        observed.set(slot, evaluate({ fixture: join(here, 'assess.py'), temp, source: location, stage, seedFile })
          .catch(() => null));
      }
      const output = await observed.get(slot);
      if (!output) { observed.delete(slot); res.end(JSON.stringify({ ...envelope, status: 'unavailable' })); return; }
      const cases = new Map(output.cases.map(item => [item.id, item]));
      const describe = item => ({ caseId: item.id, message: String(item.failure ?? 'failed').replace(/[\x00-\x08\x0b-\x1f\x7f]/gu, '').slice(0, 1100) });
      const first = q.protectedCases.map(id => cases.get(id)).find(item => item.status !== 'passed');
      const old = first ? { status: 'failed', firstError: describe(first) } : { status: 'passed' };
      const required = q.requiredCases.map(id => {
        const item = cases.get(id);
        return item.status === 'passed' ? { caseId: id, status: 'passed' } : { caseId: id, status: 'failed', error: describe(item) };
      });
      const status = old.status === 'passed' && required.every(item => item.status === 'passed') ? 'passed' : 'failed';
      res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({ ...envelope, status, old, required }));
    } catch { res.writeHead(400).end(); }
  });
}

// Exercise the real adapter before any model work. The controls use only the
// public seed and fixed recipe inputs. They never inspect private grader data.
async function preflightDiagnostics() {
  const artifacts = await Promise.all(files.map(async path => {
    const content = await readFile(join(here, 'seed', path));
    return { path, sha256: digest(content), contentBase64: content.toString('base64') };
  }));
  const controls = [
    ['wrong-argv', { recipe: 'engineering-python-syntax', args: ['outside.py'] }, 'invalid-input', 'args'],
    ['forbidden-stdin', { recipe: 'engineering-python-syntax', args: ['release.py'], stdin: 'x' }, 'invalid-input', 'stdin'],
    ['unexpected-files', { recipe: 'engineering-json', files: [{}] }, 'invalid-input', 'files'],
    ['syntax-correct', { recipe: 'engineering-python-syntax', args: ['release.py'] }, 'passed'],
    ['owner-trace-nonobject', { recipe: 'engineering-json', stdin: '[]', trace: true }, 'passed'],
    ['owner-trace-overflow', { recipe: 'engineering-json', stdin: '[]', trace: true }, 'unavailable'],
    ['running-program-timeout', { recipe: 'engineering-json', stdin: '{}' }, 'execution-timeout'],
  ];
  const looping = Buffer.from('while True:\n    pass\n', 'utf8');
  const timeoutArtifacts = artifacts.map(item => item.path === 'release.py'
    ? { path: item.path, sha256: digest(looping), contentBase64: looping.toString('base64') } : item);
  // More than 256 distinct Python lines must refuse proof, not truncate it.
  const overflow = Buffer.from(Array.from({length: 260}, (_, i) => 'v = ' + i).join('\n') + '\n');
  const overflowArtifacts = artifacts.map(item => item.path === 'release.py'
    ? { path: item.path, sha256: digest(overflow), contentBase64: overflow.toString('base64') } : item);
  const results = [];
  for (const [id, probe, status, inputError] of controls) {
    const snapshot = id === 'owner-trace-overflow' ? overflowArtifacts
      : status === 'execution-timeout' ? timeoutArtifacts : artifacts;
    const requestId = randomBytes(16).toString('hex');
    const snapshotSha256 = digest(JSON.stringify([snapshot.map(({ path, sha256 }) => [path, sha256]), probe]));
    const response = await fetch(env.DSH_BUILDING_LOOP_DIAGNOSTICS_URL, {
      method: 'POST', headers: { Authorization: 'Bearer ' + diagKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ spec: 'building-loop/diagnostics/2', requestId, snapshotSha256, operation: 'probe',
        checkSet: 'engineering-g1', artifacts: snapshot, protectedCases: [], requiredCases: [], probe }),
      signal: AbortSignal.timeout(15_000),
    });
    assert.equal(response.status, 200);
    const reply = await response.json();
    assert.equal(reply.requestId, requestId);
    assert.equal(reply.snapshotSha256, snapshotSha256);
    assert.equal(reply.status, status);
    assert.equal(reply.inputError, inputError);
    if (status === 'passed') assert.equal(reply.probe?.exitCode, 0);
    if (id === 'owner-trace-nonobject') {
      assert.equal(JSON.parse(reply.probe.stdout).error, 'invalid-request');
      assert.ok(reply.probe.executed.length > 0 && reply.probe.executed.length <= 256);
      assert.ok(reply.probe.executed.some(row => row.path === 'planner.py'));
      assert.ok(reply.probe.executed.every(row => files.includes(row.path) && Number.isInteger(row.line) && row.line > 0));
    }
    if (id === 'owner-trace-overflow') assert.equal(Object.hasOwn(reply, 'probe'), false);
    if (status === 'execution-timeout') assert.equal(Object.hasOwn(reply, 'probe'), false);
    results.push({ id, status, ...(inputError && { inputError }) });
  }
  metadata.preflightDiagnostics = results;
}

try {
  await Promise.all([home, env.APPDATA, env.LOCALAPPDATA, temp].map(path => mkdir(path, { recursive: true })));
  await Promise.all([env.NPM_CONFIG_USERCONFIG, env.NPM_CONFIG_GLOBALCONFIG, env.GIT_CONFIG_GLOBAL].map(path => writeFile(path, '')));
  const wsl = spawnSync('wsl.exe', ['-d', 'Ubuntu', '--exec', '/usr/bin/env', 'TMPDIR=' + linux(temp), 'PYTHONDONTWRITEBYTECODE=1',
    '/usr/bin/python3', linux(join(here, 'assess.py')), '--cases', linux(seedFile)], { ...context, timeout: 30_000 });
  assert.equal(wsl.status, 0, redact(wsl.stderr));
  const inventory = JSON.parse(wsl.stdout);
  server = createDiagnostics(inventory);
  await new Promise((accept, reject) => server.once('error', reject).listen(0, '127.0.0.1', accept));
  env.DSH_BUILDING_LOOP_DIAGNOSTICS_URL = 'http://127.0.0.1:' + server.address().port + '/engineering-check';
  env.DSH_BUILDING_LOOP_DIAGNOSTICS_TOKEN = diagKey;
  env.DSH_BUILDING_LOOP_DIAGNOSTICS_TIMEOUT_MS = '26000';
  if (preflight) await preflightDiagnostics();
  let init = call('--profile', 'qa', '--from-default-profile', 'web', '--help');
  for (let n = 0; n < 2 && init.status !== 0 && /EPERM.*rename/u.test(init.stderr ?? ''); n++) {
    await sleep(500 * (n + 1));
    init = call('--profile', 'qa', '--from-default-profile', 'web', '--help');
  }
  assert.equal(init.status, 0, redact(init.error?.message ?? init.stderr));
  const installed = call('plugin', '--profile', 'qa', 'add', archive, '--offline', '--store-dir', store);
  await out('install.log', redact((installed.stdout ?? '') + '\n' + (installed.stderr ?? '')));
  assert.equal(installed.status, 0, redact(installed.error?.message ?? installed.stderr));
  metadata.version = JSON.parse(await readFile(join(profile, 'node_modules/dsh-building-loop/package.json'), 'utf8')).version;
  await Promise.all([
    ...['witness.mjs','fixture.mjs','completion-interactive.mjs'].map(name => copyFile(join(here, name), join(profile, name))),
    copyFile(join(here, '../completion-policy.mjs'), join(profile, 'completion-policy.mjs')),
    copyFile(join(here, '../owner-regressions.mjs'), join(profile, 'owner-regressions.mjs')),
  ]);
  await writeFile(join(profile, 'cordis.patch.yml'), `- id: session-telemetry-otel
  disabled: true
- id: product-analytics
  disabled: true
- id: session-title-llm
  disabled: true
- id: llm-deepseek-account
  disabled: true
- id: llm-deepseek
  config:
    thinking: disabled
    maxTokens: 12288
- insert:
    - id: building-loop-engineering-comparison-witness
      name: ./witness.mjs
      config:
        run: ${yaml(run)}
        home: ${yaml(home)}
        fixtures: ${yaml(here)}
        capMs: ${capMs}
        completionMs: ${completionMs}
        preflight: ${preflight}
        modes: ${JSON.stringify(modeOrder)}
        caseInventory: ${JSON.stringify(inventory)}
        seedFile: ${yaml(seedFile)}
        suiteIdentity: ${yaml(suiteIdentity)}
`);
  await out('metadata.json', metadata);
  host = spawn(exe, ['--expose-internals', cli, '--profile', 'qa', '--no-open', '--host', '127.0.0.1', '--port', '0'],
    { ...context, stdio: ['ignore', 'pipe', 'pipe'] });
  host.stdout.on('data', data => { stdout += data; });
  host.stderr.on('data', data => { stderr += data; });
  let spawnError;
  host.on('error', error => { spawnError = error; stderr += error.message; });
  // A startup failure is distinct from a still-running model stage. Once the
  // installed witness is ready, only its result or actual host exit ends this process.
  const startupDeadline = Date.now() + 120_000;
  let ready = false;
  while (!spawnError && host.exitCode === null && host.signalCode === null) {
    if (!ready) ready = await readFile(join(run, 'witness-ready.json')).then(() => true, () => false);
    if (!ready && Date.now() >= startupDeadline) {
      metadata.status = 'witness-startup-timeout';
      break;
    }
    let result;
    try { result = JSON.parse(await readFile(join(run, 'result.json'), 'utf8')); } catch {}
    if (result) {
      metadata.status = result.error || result.lanes?.some(lane => lane.error) ? 'fixture-error' : 'observed';
      console.log(redact(result.error ?? JSON.stringify(result.lanes?.map(lane => lane.error ?? [lane.mode,
        lane.stages.map(stage => [stage.stage, stage.nativePhase, stage.final.cases.filter(item => item.status === 'passed').length])]))));
      break;
    }
    await sleep(450);
  }
  metadata.status ??= spawnError ? 'host-spawn-error' : 'host-exited';
  if (metadata.status !== 'observed') process.exitCode = 1;
} catch (error) {
  metadata.status = 'runner-error';
  metadata.error = redact(error.stack);
  console.error(metadata.error);
  process.exitCode = 1;
} finally {
  if (host?.exitCode === null) {
    host.kill();
    await Promise.race([new Promise(accept => host.once('exit', accept)), sleep(2500)]);
  }
  metadata.hostSpawned = !!host;
  metadata.isolatedHostStopped = !host || host.exitCode !== null || host.signalCode !== null;
  server?.closeAllConnections();
  server?.close();
  metadata.finishedAt = new Date().toISOString();
  metadata.formalProfileFingerprintsUnchanged = JSON.stringify(before) === JSON.stringify(await formal());
  await Promise.all([out('metadata.json', metadata), out('host.stdout.log', redact(stdout)), out('host.stderr.log', redact(stderr))]);
}

witness.mjs.text:
import { generateKeyPairSync, randomUUID, sign } from 'node:crypto';
import { appendFileSync, existsSync, readFileSync, readdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { setTimeout as sleep } from 'node:timers/promises';
import { pathToFileURL } from 'node:url';
import { decideCompletion, timeWindow, verifyCompletionPolicy } from './completion-policy.mjs';
import { inputWait, verifyInteractivePolicy } from './completion-interactive.mjs';
import { releaseRollbackDiagnostics } from './owner-regressions.mjs';
import { digest, evaluate, files, fingerprint, materialize, rows, save, snapshot } from './fixture.mjs';

const plugin = dirname(createRequire(import.meta.url).resolve('dsh-building-loop/package.json'));
const { parseAuthority } = await import(pathToFileURL(join(plugin, 'governance/policy.mjs')));
const { codeRegressionSigningBytes } = await import(pathToFileURL(join(plugin, 'governance/code-intake.mjs')));
const packageVersion = JSON.parse(readFileSync(join(plugin, 'package.json'), 'utf8')).version;
const revisedArchitecture = ['0.7.29', '0.7.30'].includes(packageVersion);
const model = { provider: 'deepseek-official', model: 'deepseek-flash', reasoningEffort: 'off' };
export const name = 'building-loop-engineering-comparison-witness';
export const inject = ['agentPresets', 'agents', 'sessionController', 'typertGateway'];

const goalFiles = ['PROJECT-GOAL.md', 'SPEC.md', 'CHANGE-G2.md'];
const planFile = 'modules/architecture.md';
// The existing SPEC fixes request type and the public suite already fixes the
// response. The owner policy explicitly locates the business check in planner.
const architectureResponsibilities = {
  responsibilitiesHeading: '模块职责',
  responsibilities: [{
    id: 'nonobject-request',
    mode: 'business',
    trigger: { kind: 'input-type', argument: 0, type: 'object', test: 'not' },
    owner: { file: 'planner.py' },
    exampleId: 'public-architecture-responsibility:example:nonobject-request',
  }],
};
const responsibilityExample = {
  id: 'public-architecture-responsibility', recipe: 'engineering-json',
  examples: [{
    id: 'nonobject-request', input: [], expectedExitCode: 0,
    expectedJson: { status: 'error', error: 'invalid-request', actions: [], units: 0 },
    requirement: { file: 'SPEC.md', start: 5, end: 5,
      quote: 'An input is an object with `environment` (`staging` or `production`), `action` (`plan` or `rollback` when supported by the current goal), nonnegative integer `budget`, and `changes` (array of records).' },
  }],
};
const projectDocs = /\.(?:md|markdown|rst|txt|adoc)$/iu;
const isBuilding = mode => mode === 'building-loop';
const trimCases = output => output.cases.map(({ id, status }) => ({ id, status }));
const finish = new Set(['closed', 'retired']);
const g1Message = '开始建设：把这个发布规划器的批量回退按 SPEC.md 做完，之前正常的行为和接口保住。做完告诉我结果。工作单元 K01。';
const g2Message = '开始建设：上轮这个发布规划器继续做。批量回退要求变了，以 CHANGE-G2.md 的 G4 修订为准，其他现有行为保住。做完告诉我结果。工作单元 K02。';
const checklist = [
  '先规划再实现，在项目里留下可供下一次会话接手的架构说明。',
  '把模块职责、依赖方向、实施和回退顺序及验证方法写清楚。',
  '在实际负责重放计费、图排序和失败保护的关键代码旁，解释非显然的原因或边界。',
  '按现行需求运行测试，记录通过、失败及未完成事项，留在项目内供接手。',
  '目标变更时检查已有文件和测试，修正过期的规划与说明并保留适用的旧行为。',
].join(' ');
function document(stage, building) {
  const goal = stage === 'g1'
    ? '# Release project\n\n当前目标 G3，按 SPEC.md 完成批量回退。\n'
    : '# Release project\n\n当前目标 G4，按 CHANGE-G2.md 更新，SPEC.md 其余要求继续有效。\n';
  return building ? goal + '\n## 分块入口\n\n- [分块索引](INDEX.md)\n' : goal;
}

function draftNotes() {
  return '# 发布规划与维护\n\n## 模块职责\n\n由宿主生成。请保留本节。\n\n## 实施顺序\n\n待填写。\n\n## 回退顺序\n\n待填写。\n\n## 关键验证\n\n待填写。\n\n## 静态导入\n\n待由宿主生成。\n';
}

// Register shape checks from the public transport contract. Private graph cases
// remain exclusively in the evaluator, outside all workspace material.
const transportResult = { status: 'ok', actions: ['probe-item'], units: 1 };
const shapeError = error => ({ status: 'error', error, actions: [], units: 0 });
const transportSeed = { environment: 'staging', action: 'plan', budget: 2,
  changes: [{ id: 'probe-item', component: 'probe-component', units: 1, depends_on: [] }], applied: [] };

function publicInputContracts(withRetention) {
  const transport = {
    id: 'public-transport-shapes', recipe: 'engineering-json', seed: transportSeed, expectedJson: transportResult,
    checks: [
      { path: [], invalid: ['array', 'null'], expectedJson: shapeError('invalid-request') },
      { path: ['environment'], invalid: ['array', 'object', 'null', 'boolean', 'number', 'missing'],
        expectedJson: shapeError('invalid-environment') },
      { path: ['budget'], invalid: ['array', 'null', 'boolean', 'string', 'missing'], expectedJson: shapeError('invalid-budget') },
      { path: ['changes'], invalid: ['object', 'null', 'string'], expectedJson: shapeError('invalid-change') },
      { path: ['action'], invalid: ['array', 'object', 'null'], expectedJson: shapeError('unsupported-action') },
      { path: ['changes', 0, 'depends_on'], invalid: withRetention ? ['null'] : ['null', 'object'],
        expectedJson: shapeError('invalid-change') },
      { path: ['applied'], invalid: withRetention ? ['null'] : ['null', 'object'], expectedJson: shapeError('invalid-change') },
    ],
  };
  if (!withRetention) return [transport];
  return [transport, {
    id: 'public-rollback-retain', recipe: 'engineering-json',
    seed: { ...transportSeed, action: 'rollback', applied: ['probe-item'], retain: [] }, expectedJson: transportResult,
    checks: [{ path: ['retain'], invalid: ['null'], expectedJson: shapeError('invalid-retain') }],
  }];
}

// The old reference archive can still run the exact same business fixtures.
const typedRecipeInputs = existsSync(join(plugin, 'governance/diagnostic-recipe-inputs.mjs')) ? {
  recipeInputs: {
    'engineering-json': { args: { min: 0, types: [] }, stdin: 'optional', files: { min: 0, max: 0 } },
    'engineering-python-syntax': { args: { min: 1, types: ['source'] }, stdin: 'forbidden', files: { min: 0, max: 0 } },
  },
} : {};

export function units(publicKey, cases, suiteDigest, publicExamples, fixtureBase) {
  const config = (stage, previous, current) => {
    const id = stage === 'g1' ? 'K01' : 'K02';
    const read = [...files, 'INDEX.md', planFile];
    const edit = { read, write: files };
    return { candidate: 'release.py', plainLast: false, continuation: 'fresh',
      architecture: { module: 'architecture', headings: ['实施顺序', '回退顺序', '关键验证'],
        ...(revisedArchitecture ? { proseReview: true } : {}),
        importsHeading: '静态导入', allowedLocalImports: [{ file: 'release.py', imports: ['planner.py'] }],
        ...architectureResponsibilities },
      codeTask: { sources: files, diagnostics: { checkSet: 'engineering-' + stage, protocol: 2,
        recipes: ['engineering-json', 'engineering-python-syntax'], reviewRecipes: ['engineering-json', 'engineering-python-syntax'],
        syntaxRecipe: 'engineering-python-syntax', inputContracts: [
          ...publicInputContracts(true),
          responsibilityExample,
          ...(revisedArchitecture ? [releaseRollbackDiagnostics(fixtureBase)] : []),
          ...(publicExamples[stage] ? [{ id: 'public-batch-behavior', recipe: 'engineering-json', examples: publicExamples[stage] }] : []),
        ], ...typedRecipeInputs },
        tests: { file: '.candidate-' + id + '.json', publicKey,
          previousSuiteSha256: digest(suiteDigest + ':' + previous), suiteSha256: digest(suiteDigest + ':' + current),
          requiredCases: cases[current].filter(key => !cases[previous].includes(key)),
          regression: { baselineFile: '.baseline-' + id + '.json', previousCases: cases[previous] } } },
      phases: { intake: edit, supplement: edit,
        'first-review': { read, evidence: [], receipt: 'receipts/' + id + '-first.json' },
        'final-review': { read, evidence: [], receipt: 'receipts/' + id + '-final.json' } } };
  };
  return { K01: config('g1', 'base', 'g1'), K02: config('g2', 'carry', 'g2') };
}

function signed(body, key) {
  return { ...body, signature: sign(null, codeRegressionSigningBytes(body), key).toString('base64') };
}

function sealBaseline(root, unit, policy, result, key) {
  const spec = policy.units[unit].codeTask.tests;
  save(root, spec.regression.baselineFile, signed({ spec: 'building-loop-code-regression-baseline/1',
    unit, policySha256: policy.hash, suiteSha256: spec.previousSuiteSha256, artifacts: rows(snapshot(root)),
    runId: 'bench-' + unit + '-baseline', cases: trimCases(result) }, key));
}

function sideFacts(root) {
  const docs = {};
  let remaining = 256 * 1024;
  function visit(directory = '', depth = 0) {
    if (depth > 4 || Object.keys(docs).length >= 48 || remaining <= 0) return;
    const here = join(root, directory);
    for (const entry of readdirSync(here, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      if (entry.name.startsWith('.') || entry.isSymbolicLink() || /^(?:node_modules|__pycache__|receipts)$/u.test(entry.name)) continue;
      const path = directory ? directory + '/' + entry.name : entry.name;
      if (entry.isDirectory()) visit(path, depth + 1);
      else if (entry.isFile() && projectDocs.test(path)) {
        const bytes = readFileSync(join(root, path));
        if (bytes.length > 64 * 1024 || bytes.length > remaining || Object.keys(docs).length >= 48) continue;
        const text = bytes.toString('utf8');
        if (text.includes('\0')) continue;
        docs[path] = { sha256: digest(bytes), text };
        remaining -= bytes.length;
      }
    }
  }
  visit();
  return docs;
}

function copyState(root, facts) {
  for (const [path, { text }] of Object.entries(facts)) save(root, path, text);
}

function additionalPythonFiles(root, directory = '', output = []) {
  for (const entry of readdirSync(join(root, directory), { withFileTypes: true })) {
    if (entry.name === '.git' || entry.name === '__pycache__' || entry.isSymbolicLink()) continue;
    const name = directory ? directory + '/' + entry.name : entry.name;
    if (entry.isDirectory()) additionalPythonFiles(root, name, output);
    else if (entry.isFile() && name.endsWith('.py') && !files.includes(name)) output.push(name);
  }
  return output.sort();
}

export function apply(ctx, config) {
  const { run, home, fixtures, capMs, completionMs, modes, caseInventory, seedFile, suiteIdentity } = config;
  const memberships = new Map();
  const eventPath = join(run, 'events.jsonl');
  const progress = (event, value) => appendFileSync(join(run, 'progress.jsonl'), JSON.stringify({ time: Date.now(), event, ...value }) + '\n');
  const keys = generateKeyPairSync('ed25519');
  const publicKey = keys.publicKey.export({ format: 'der', type: 'spki' }).toString('base64');
  const assessPath = join(fixtures, 'assess.py');
  const suiteDigest = suiteIdentity;
  const publicExamples = ['0.7.27', '0.7.28', '0.7.29', '0.7.30'].includes(packageVersion)
    ? JSON.parse(readFileSync(join(fixtures, 'public-input-examples.json'), 'utf8')) : {};
  const manifest = {
    spec: 'building-loop/1', goalContext: goalFiles, ledgerContext: goalFiles, ledgerDocument: 'LEDGER.md',
    coordinator: { read: [...goalFiles, 'INDEX.md', planFile, 'LEDGER.md',
      ...['K01', 'K02'].flatMap(id => ['receipts/' + id + '-first.json', 'receipts/' + id + '-final.json'])],
      write: [planFile, 'LEDGER.md'] },
    hierarchy: { overview: { path: 'PROJECT-GOAL.md', heading: '分块入口' },
      index: { path: 'INDEX.md', heading: '模块正文' }, modules: { architecture: planFile } },
    units: units(publicKey, caseInventory, suiteDigest, publicExamples, pathToFileURL(join(fixtures, '/'))),
  };
  const authorityBytes = JSON.stringify(manifest);
  const policy = parseAuthority(Buffer.from(authorityBytes));
  const seed = snapshot(join(fixtures, 'seed'));

  function state(owner, id) {
    const directory = join(home, 'building-loop-state');
    if (!existsSync(directory)) return null;
    for (const file of readdirSync(directory).filter(name => /^[a-f0-9]{64}\.json$/u.test(name))) {
      const stored = JSON.parse(readFileSync(join(directory, file), 'utf8'));
      if (stored.units?.[id]?.owner === owner || stored.engineeringCoordinator?.session === owner &&
        stored.engineeringCoordinator?.unit === id) return stored;
    }
    return null;
  }

  function signLatest(group) {
    const { challenge, latest } = group;
    if (!challenge || !latest?.results || latest.hash !== group.liveHash ||
      challenge.unit !== group.unit || fingerprint(snapshot(group.root)) !== latest.hash) return;
    const key = digest(JSON.stringify([challenge.goalSha256, challenge.nonce, latest.hash]));
    if (group.signed.has(key)) return;
    const { file, previousCases, requiredCases, protectedCases, artifacts: previousArtifacts, ...binding } = challenge;
    const expected = [...previousCases, ...requiredCases].sort();
    if (JSON.stringify(expected) !== JSON.stringify(latest.results.cases.map(row => row.id).sort())) return;
    // The trusted runner owns its snapshot and can sign changed bytes without
    // waiting for the model to request the same unit nonce and goal again.
    const receipt = signed({ ...binding, artifacts: latest.artifacts, runId: 'bench-' + key.slice(0, 20),
      cases: trimCases(latest.results) }, keys.privateKey);
    save(group.root, file, receipt);
    group.signed.add(key);
    progress('signed', { mode: group.mode, stage: group.stage, hash: latest.hash, goalSha256: binding.goalSha256,
      elapsedMs: Date.now() - group.started, protected: protectedCases.length, required: requiredCases.length,
      jointPass: [...protectedCases, ...requiredCases].every(id =>
        latest.results.cases.find(row => row.id === id).status === 'passed') });
  }

  ctx.on('session/event', (session, event) => {
    const parent = session.header?.parentSession;
    const group = memberships.get(session.id) ?? memberships.get(parent);
    if (!group || group.stopped) return;
    memberships.set(session.id, group);
    group.lastActivityAt = Date.now();
    if (!['assistant/message', 'assistant/attempt', 'request/header', 'tool/result', 'turn/end'].includes(event.type)) return;
    const { data } = event;
    const unit = group.unit;
    const current = isBuilding(group.mode) ? state(group.id, unit)?.units?.[unit] : null;
    const role = session.id === group.id ? isBuilding(group.mode) ? 'coordinator' : 'standard'
      : session.id === current?.diagnostician || session.id === current?.stallDiagnostic?.diagnostician ? 'diagnostician'
        : session.id === current?.auditor ? 'auditor' : session.id === current?.reviewer ? 'reviewer' : 'executor';
    const elapsedMs = Date.now() - group.started;
    const row = { mode: group.mode, stage: group.stage, session: digest(session.id).slice(0, 12), role, seq: event.seq,
      type: event.type, elapsedMs, window: timeWindow(elapsedMs, capMs, group.frozenMs) };
    // Record public diagnostic phase/version summaries and role usage without storing model inputs.
    if (current?.stallDiagnostic && /^[a-f0-9]{64}$/u.test(current.stallDiagnostic.artifactSha256 ?? '')) {
      const { status, suggestedLayer, layer, failureKind, repeatCount, trigger, artifactSha256 } = current.stallDiagnostic;
      row.stallDiagnostic = { status, suggestedLayer, layer, failureKind, repeatCount, trigger, artifactSha256 };
      if (current.stallDiagnostic.caseId === 'rollback-order') {
        row.stallDiagnostic.caseId = 'rollback-order';
        const attempts = current.stallDiagnostic.registeredReplay?.attempts;
        if (attempts) row.stallDiagnostic.registered = Object.fromEntries(Object.entries(attempts)
          .filter(([id]) => id.startsWith('public-rollback-order-diagnostics:example:')));
      }
    }
    if (event.type === 'assistant/message') {
      row.usage = data.usage;
      row.provider = data.message?.source?.provider;
      row.model = data.message?.source?.model;
      row.calls = (data.message?.content ?? []).filter(part => part.type === 'tool-call').map(part => {
        let args = part.arguments;
        try { if (typeof args === 'string') args = JSON.parse(args); } catch { args = {}; }
        const dedicatedReview = part.name === 'building_loop_code_review';
        return { name: part.name,
          action: args?.action ?? (dedicatedReview ? role === 'auditor' ? 'audit' : 'review' : undefined),
          unit: /^K0[12]$/u.test(args?.unit) ? args.unit : undefined,
          ...(dedicatedReview && args?.action === 'record' ? {
            compactDecisions: Array.isArray(args.decisions) ? args.decisions.length : 0,
            legacyRows: ['files', 'constraints'].reduce((total, key) => total + (args[key]?.length ?? 0), 0) +
              (args.architecture?.sections?.length ?? 0),
          } : {}),
          path: typeof (args?.path ?? args?.file_path) === 'string' &&
            /^(?:[A-Za-z0-9_. -]+\/)*[A-Za-z0-9_. -]{1,120}$/u.test(args.path ?? args.file_path)
            ? (args.path ?? args.file_path) : undefined,
          ...(dedicatedReview && args?.action === 'probe' ? {
            assertion: ['syntax', 'runtime', 'architecture'].includes(args.assertion) ? args.assertion : undefined,
            exampleId: /^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$/u.test(args.exampleId ?? '') ? args.exampleId : undefined,
            file: files.includes(args.file) ? args.file : undefined,
          } : part.name === 'building_loop_reproduce' && args?.action === 'example' ? {
            exampleId: /^[A-Za-z0-9][A-Za-z0-9._:-]{0,120}$/u.test(args.exampleId ?? '') ? args.exampleId : undefined,
          } : {}) };
      });
    } else if (event.type === 'assistant/attempt') row.error = data.stream?.error?.code ?? data.stream?.error?.name;
    else if (event.type === 'request/header') row.tools = data.header?.tools?.map(tool => tool.name);
    else if (event.type === 'turn/end') {
      row.reason = data.reason?.kind;
      if (session.id === group.id) {
        group.rootEnded = row.reason;
        group.rootEnd = { reason: row.reason, elapsedMs };
      }
    } else if (event.type === 'tool/result') {
      row.error = data.message?.isError;
      const resultText = data.message?.content?.find(item => item.type === 'text')?.text;
      if (row.error) row.detail = String(resultText ?? '').slice(0, 450);
      else {
        try {
          const result = JSON.parse(resultText);
          const challenge = result.codeTask?.regressionProof;
          if (challenge?.unit === unit) {
            group.challenge = challenge;
            signLatest(group);
          }
          if (result.phase) row.phase = result.phase;
          if (typeof result.reused === 'boolean' && typeof result.childId === 'string') {
            row.assignment = { reused: result.reused, child: digest(result.childId).slice(0, 12) };
          }
          if (typeof result.diagnostics?.status === 'string') row.editDiagnostics = { status: result.diagnostics.status };
          if (/^stall-proof-[a-f0-9]{64}$/u.test(result.proofId ?? '')) row.stallProofId = result.proofId;
          if (['invalid-input', 'timeout', 'execution-timeout', 'unavailable'].includes(result.status)) {
            row.diagnosticFailure = { status: result.status,
              field: ['args', 'stdin', 'files'].includes(result.field) ? result.field : undefined };
          }
          if (/^public-batch-behavior:[A-Za-z0-9._:-]{1,100}$/u.test(result.exampleId ?? '') &&
              ['match', 'mismatch', 'unavailable'].includes(result.outcome)) {
            row.publicExample = { id: result.exampleId, outcome: result.outcome, status: result.status };
          }
          if (result.submission?.status === 'input-check') {
            const input = result.submission.inputContracts;
            row.inputContractCheck = { status: input?.status, passed: input?.passed, total: input?.total,
              failed: input?.failures?.map(({ id, shape, outcome, actual, status, reason }) =>
                ({ id, shape, outcome, actual, status, reason })) };
          }
          if (result.submission?.status === 'architecture-responsibility') {
            row.architectureResponsibilityCheck = result.submission.rows?.slice(0, 8).map(
              ({id, status, reason, actual}) => ({id, status, reason, actual}));
          }
          if (result.architecture?.contract) {
            row.architectureResponsibilityStatus = result.architecture.contract.slice(0, 8).map(
              ({id, status, decision, traceSha256}) => ({id, status, decision, traceSha256}));
          }
          if (['rollback-plan-required', 'rollback-failed', 'rollback-unavailable'].includes(result.status)) {
            row.rollbackRehearsal = { status: result.status, reason: result.reason?.slice(0, 400), ...result.rollback };
          }
          if (result.status === 'registered' && /^rollback-[a-f0-9]{64}$/u.test(result.id ?? '')) {
            row.rollbackProposalRegistered = { id: result.id, files: result.files?.filter(path => files.includes(path)) };
          }
          if (result.rollbackRepair?.id) {
            const { id, proposalId, failures, checkReceipts } = result.rollbackRepair;
            row.rollbackRepair = { id, proposalId, failedChecks: failures?.map(({ id }) => id),
              observedChecks: checkReceipts?.length };
          }
          if (result.architecture?.rollbackRehearsal) {
            const { status, passed, total, binding, changed, receipts } = result.architecture.rollbackRehearsal;
            row.rollbackRehearsal = { status, passed, total, binding, changed, receipts };
          }
          if (result.reviewProgress?.blockingFindings) row.blockingFindings = result.reviewProgress.blockingFindings;

          if (result.status === 'needs-review') {
            row.needsReview = { message: result.message?.slice(0, 600), next: result.next, progress: result.progress };
          }
          if (Array.isArray(result.architecture?.conflicts) && result.architecture.conflicts.length) {
            row.architectureConflicts = result.architecture.conflicts.slice(0, 32);
          }
          if (typeof result.checkpoint?.unit === 'string' && /^K0[12]$/u.test(result.checkpoint.unit)) {
            row.boundCheckpoint = { unit: result.checkpoint.unit, goalSha256: result.checkpoint.goalSha256 };
          }
          if (result.codeReview || result.readiness || result.codeSubmission) {
            row.observedContract = Object.keys(result).filter(key => /code|readiness/i.test(key));
          }
          const summarizeProbe = probe => /^probe-[a-f0-9]{36}$/u.test(probe?.id ?? '') &&
            ['match', 'mismatch', 'unavailable'].includes(probe.outcome) ? { id: probe.id, outcome: probe.outcome,
              assertion: ['syntax', 'runtime', 'architecture'].includes(probe.type) ? probe.type : undefined,
              exampleId: /^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$/u.test(probe.exampleId ?? '') ? probe.exampleId : undefined,
              recipe: ['engineering-json', 'engineering-python-syntax'].includes(probe.recipe) ? probe.recipe : undefined,
              snapshotSha256: /^[a-f0-9]{64}$/u.test(probe.snapshotSha256 ?? '') ? probe.snapshotSha256 : undefined,
              expectedExitCode: probe.expected?.exitCode, actualExitCode: probe.actual?.exitCode } : undefined;
          const proof = summarizeProbe(result);
          if (proof) row.probe = proof;
          if (Array.isArray(result.examples)) {
            row.exampleProbes = result.examples.slice(0, 8).map(summarizeProbe).filter(Boolean);
          }
        } catch {}
      }
    }
    appendFileSync(eventPath, JSON.stringify(row) + '\n');
  });

  function observe(group) {
    const current = snapshot(group.root);
    const hash = fingerprint(current);
    if (hash !== group.liveHash) {
      group.liveHash = hash;
      group.changed = Date.now();
      progress('source', { mode: group.mode, stage: group.stage, hash, elapsedMs: group.changed - group.started });
    }
    if (group.running || group.startedHashes.has(hash) || Date.now() - group.changed < 350) return;
    group.startedHashes.add(hash);
    const source = join(run, 'assess', group.mode, group.stage, hash.slice(0, 20));
    materialize(source, current);
    group.running = evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source, stage: group.stage, seedFile })
      .then(results => {
        save(source, 'assessment.json', results);
        if (group.stopped || hash !== group.liveHash) return;
        group.latest = { hash, results, artifacts: rows(current) };
        signLatest(group);
        progress('assessed', { mode: group.mode, stage: group.stage, hash, elapsedMs: Date.now() - group.started,
          passed: results.cases.filter(caseRow => caseRow.status === 'passed').length, total: results.cases.length });
      })
      .catch(error => { group.problems.push({ phase: 'observer', name: error.name, code: error.code }); })
      .finally(() => { group.running = null; });
  }

  function stageAgents(group, active) {
    const ids = new Set([group.id, active?.actor, active?.executor, active?.reviewer, active?.auditor,
      active?.diagnostician, active?.stallDiagnostic?.diagnostician]);
    for (const [id, membership] of memberships) if (membership === group) ids.add(id);
    return Array.from(ids).filter(Boolean).map(id => ctx.agents.get(id)).filter(Boolean);
  }

  function idle(agent) {
    return agent.status === 'idle' && !agent.inbox?.nextTurn?.length;
  }

  function roleIdentities(active) {
    return active && Object.fromEntries(['executor', 'reviewer', 'auditor'].filter(role => active[role])
      .map(role => [role, digest(active[role]).slice(0, 12)]));
  }

  function capture(group, phase, active, stored, terminal, target) {
    const after = snapshot(group.root);
    const facts = sideFacts(group.root);
    const extraPython = additionalPythonFiles(group.root);
    materialize(target, after);
    copyState(target, facts);
    const registration = active?.engineeringArchitecture ?? stored?.engineeringArchitecture?.[planFile];
    return { after, facts, target, elapsedMs: Date.now() - group.started, terminal, nativePhase: phase ?? null,
      extraPython,
      roleIdentity: roleIdentities(active), acceptedProofSha256: active?.codeIntake?.qualification?.receiptSha256,
      architectureResponsibilities: active?.codeIntake?.qualification?.architectureResponsibilities,
      rollbackRehearsal: registration?.rollbackRehearsal,
      rollbackProposal: registration?.rollbackRehearsal?.binding?.proposalId === active?.rollbackProposal?.id ? active?.rollbackProposal : undefined,
      registeredArchitecture: registration && { file: registration.file, sha256: registration.sha256,
        contentsSha256: registration.contentsSha256, goalSha256: registration.goalSha256 },
      ledgerItems: Object.values(stored?.ledger?.items ?? {}).map(({ id, kind, status, owner, originalOwner, handedOffFrom }) => ({
        id, kind, status, owner: owner && digest(owner).slice(0, 12), originalOwner: originalOwner && digest(originalOwner).slice(0, 12),
        handedOffFrom: handedOffFrom && digest(handedOffFrom).slice(0, 12) })) };
  }

  async function stopOnlyStage(group, active) {
    const attempted = [];
    const failed = [];
    const until = Date.now() + 6_000;
    while (Date.now() < until) {
      const running = stageAgents(group, active).filter(agent => !idle(agent));
      if (!running.length) return { attempted, failed, allIdle: true };
      for (const agent of running) {
        const id = digest(agent.id).slice(0, 12);
        if (attempted.includes(id)) continue;
        attempted.push(id);
        try { agent.cancel({ kind: 'user' }, { keepInbox: false }); }
        catch (error) { failed.push({ id, name: error.name }); }
      }
      await sleep(150);
    }
    return { attempted, failed, allIdle: stageAgents(group, active).every(idle) };
  }

  async function runStage(mode, preset, stage, root, origin) {
    const unit = stage === 'g1' ? 'K01' : 'K02';
    const baselineStage = stage === 'g1' ? 'base' : 'carry';
    const before = snapshot(root);
    const basePath = join(run, 'baseline', mode, stage);
    materialize(basePath, before);
    const baseline = await evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source: basePath, stage: baselineStage, seedFile });
    save(basePath, 'assessment.json', baseline);
    if (isBuilding(mode)) sealBaseline(root, unit, policy, baseline, keys.privateKey);
    const { sessionId: id } = await ctx.sessionController.create({ cwd: root, agentPreset: preset });
    await ctx.sessionController.selectModel({ sessionId: id, ...model });
    const group = { id, mode, stage, unit, root, problems: [], signed: new Set(), startedHashes: new Set(), started: Date.now(),
      lastActivityAt: Date.now() };
    memberships.set(id, group);
    const ordinary = stage === 'g1' ? g1Message : g2Message;
    const prompt = mode === 'standard-checklist' ? ordinary + '\n\n' + checklist : ordinary;
    observe(group);
    const accepted = await ctx.sessionController.prompt({ sessionId: id, requestId: randomUUID(), clientTimeZone: 'Asia/Shanghai',
      content: [{ type: 'text', text: prompt }] }, AbortSignal.timeout(8_000));
    if (!accepted.accepted) throw Error('Native user prompt was not accepted for ' + mode + '/' + stage);
    let decision, stored, active, phase, waiting;
    const observations = [];
    const milestones = {};
    const frozenRoot = join(run, 'frozen', mode, stage);
    const observationTargets = [
      [capMs, join(run, 'checkpoint', mode, stage)],
      [completionMs, join(run, 'checkpoint-600', mode, stage)],
    ];
    while (!decision) {
      stored = isBuilding(mode) ? state(id, unit) : null;
      active = stored?.units?.[unit]?.owner === id ? stored.units[unit] : undefined;
      const elapsedMs = Date.now() - group.started;
      if (active?.phase !== phase) {
        phase = active?.phase;
        group.lastActivityAt = Date.now();
        progress('phase', { mode, stage, phase, elapsedMs });
      }
      if (finish.has(phase) && milestones.hostWorkflowEnd === undefined) {
        milestones.hostWorkflowEnd = { phase, elapsedMs };
        progress('host-workflow-end', { mode, stage, phase, elapsedMs });
      }
      const agents = stageAgents(group, active);
      waiting = inputWait(ctx.typertGateway, agents, idle);
      decision = decideCompletion({ elapsedMs, phase, rootEnded: group.rootEnded,
        allIdle: agents.length > 0 && agents.every(idle), quietMs: Date.now() - group.lastActivityAt,
        assessmentPending: !!group.running, building: isBuilding(mode),
        operatorStop: existsSync(join(run, 'operator-stop')) });
      if (!decision && waiting) decision = { terminal: 'waiting-user', classification: 'native-input-required',
        inputKinds: waiting.kinds, waitingAgents: waiting.agents.length };
      for (const [targetMs, target] of observationTargets) {
        if (elapsedMs < targetMs || observations.some(row => row.targetMs === targetMs)) continue;
        const value = capture(group, phase, active, stored, 'observation', target);
        observations.push({ targetMs, ...value });
        progress('benchmark-observation', { mode, stage, phase, elapsedMs: value.elapsedMs, targetMs,
          hash: fingerprint(value.after) });
        if (targetMs === capMs) progress('comparison-cap', { mode, stage, phase, elapsedMs: value.elapsedMs,
          hash: fingerprint(value.after) });
      }
      if (!decision) {
        observe(group);
        await sleep(150);
      }
    }
    const frozen = capture(group, phase, active, stored, decision.terminal, frozenRoot);
    group.frozenMs = frozen.elapsedMs;
    const elapsedQuietMs = Date.now() - group.lastActivityAt;
    const rootTurnEndAtDecision = group.rootEnd;
    progress('benchmark-terminal', { mode, stage, phase, elapsedMs: frozen.elapsedMs, ...decision, elapsedQuietMs });
    const cleanup = ['administrative', 'native-input-required'].includes(decision.classification)
      ? await stopOnlyStage(group, active) : { attempted: [], failed: [], allIdle: true };
    group.stopped = true;
    // Identical bytes in the same stage and frozen suite have one grade.
    const grades = new Map();
    function grade(point) {
      const key = fingerprint(point.after);
      if (!grades.has(key)) grades.set(key,
        evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source: point.target, stage, seedFile }));
      return grades.get(key);
    }
    const final = await grade(frozen);
    const scored = await Promise.all(observationTargets.map(async ([targetMs]) => {
      const observed = observations.find(row => row.targetMs === targetMs);
      const point = observed ?? frozen;
      return { targetMs, carriedForward: !observed, elapsedMs: point.elapsedMs, terminal: point.terminal,
        nativePhase: point.nativePhase, after: rows(point.after), documents: point.facts, notes: point.facts[planFile] ?? null,
        ledgerItems: point.ledgerItems, extraPython: point.extraPython, acceptedProofSha256: point.acceptedProofSha256,
        registeredArchitecture: point.registeredArchitecture, assessment: observed ? await grade(point) : final };
    }));
    const comparison = scored[0];
    const completion = { ...decision, elapsedMs: frozen.elapsedMs, quietMs: elapsedQuietMs,
      hostWorkflowEnd: milestones.hostWorkflowEnd, rootTurnEnd: rootTurnEndAtDecision };
    const result = { mode, stage, unit, capMs, completionMs, elapsedMs: frozen.elapsedMs, terminal: frozen.terminal,
      nativePhase: frozen.nativePhase, carry: origin, session: digest(id).slice(0, 12), roleIdentity: frozen.roleIdentity,
      prompt, targetFiles: goalFiles.map(path => ({ path, sha256: frozen.facts[path]?.sha256 })),
      before: rows(before), after: rows(frozen.after), baseline, final,
      documents: frozen.facts, notes: frozen.facts[planFile] ?? null, ledger: frozen.facts['LEDGER.md'] ?? null, ledgerItems: frozen.ledgerItems, extraPython: frozen.extraPython,
      architectureResponsibilities: frozen.architectureResponsibilities,
      rollbackRehearsal: frozen.rollbackRehearsal,
      rollbackProposal: frozen.rollbackProposal,
      registeredArchitecture: frozen.registeredArchitecture,
      acceptedProofSha256: frozen.acceptedProofSha256, problems: group.problems, cleanup,
      comparison, observations: scored, completion };
    save(run, mode + '-' + stage + '.json', result);
    const handoffSafe = !isBuilding(mode) ? decision.terminal === 'completed' : finish.has(decision.terminal);
    return { result, after: frozen.after, afterFacts: frozen.facts, root, handoffSafe };
  }

  async function lane(mode, preset) {
    const short = isBuilding(mode) ? 'bl' : mode === 'standard-checklist' ? 'check' : 'std';
    const laneRoot = join(run, 'work', short);
    materialize(laneRoot, seed);
    save(laneRoot, 'PROJECT-GOAL.md', document('g1', isBuilding(mode)));
    save(laneRoot, 'SPEC.md', readFileSync(join(fixtures, 'SPEC.md'), 'utf8'));
    save(laneRoot, 'CHANGE-G2.md', '# 未发布目标\n\n当前未有后续修订。\n');
    if (isBuilding(mode)) {
      save(laneRoot, 'INDEX.md', '# 工程索引\n\n## 模块正文\n\n- [architecture](modules/architecture.md)\n');
      save(laneRoot, planFile, draftNotes());
      save(laneRoot, 'BUILDING-LOOP.json', authorityBytes);
    }
    const first = await runStage(mode, preset, 'g1', laneRoot, 'same-frozen-seed');
    if (first.result.terminal === 'operator-censored') return { mode, stages: [first.result] };
    // A native handoff keeps the live project. An incomplete or failed
    // stage carries only its actual frozen work into a labeled separate workspace.
    const continuation = first.handoffSafe ? laneRoot : join(run, 'work', short + '2');
    if (continuation !== laneRoot) {
      materialize(continuation, first.after);
      copyState(continuation, first.afterFacts);
      if (isBuilding(mode)) save(continuation, 'BUILDING-LOOP.json', authorityBytes);
    }
    save(continuation, 'PROJECT-GOAL.md', document('g2', isBuilding(mode)));
    save(continuation, 'CHANGE-G2.md', readFileSync(join(fixtures, 'CHANGE-G2.md'), 'utf8'));
    progress('owner-change', { mode, from: 'g1', to: 'g2', sameWorkspace: continuation === laneRoot,
      previous: fingerprint(first.after), nextGoal: digest(document('g2', isBuilding(mode))), previousOwner: first.result.session,
      previousTerminal: first.result.terminal, previousLedgerSha256: first.afterFacts['LEDGER.md']?.sha256,
      newRequirementSha256: digest(readFileSync(join(continuation, 'CHANGE-G2.md'))) });
    const carry = continuation === laneRoot ? 'same-workspace-new-session' : ({
      blocked: 'frozen-workspace-continuation-after-block',
      'stalled-idle': 'frozen-workspace-continuation-after-idle-stall',
      'waiting-user': 'frozen-workspace-continuation-after-user-input-required',
    })[first.result.terminal] ?? 'frozen-workspace-continuation-after-native-error';
    const second = await runStage(mode, preset, 'g2', continuation, carry);
    return { mode, stages: [first.result, second.result] };
  }

  let begun = false;
  const timer = setInterval(async () => {
    if (begun) return;
    begun = true;
    try {
      const presets = await ctx.agentPresets.list();
      const standard = presets.find(item => item.id === 'standard' || item.id === 'default');
      const bl = presets.find(item => item.id === 'building-loop');
      if (!standard || !bl) { begun = false; return; }
      clearInterval(timer);
      const completionControls = verifyCompletionPolicy();
      const interactiveControls = verifyInteractivePolicy();
      if (!Array.isArray(ctx.typertGateway.getPendingRemoteEvents())) throw Error('Native pending-input observer unavailable');
      save(run, 'witness-ready.json', { model, observationMs: [capMs, completionMs], completionControls, interactiveControls });
      if (config.preflight) {
        const source = join(run, 'preflight-seed');
        materialize(source, seed);
        const result = await evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source, stage: 'base', seedFile });
        if (result.cases.some(row => row.status !== 'passed')) throw Error('Frozen base fixture failed');
        save(run, 'result.json', { model, capMs, lanes: [], preflight: { presets: [standard.id, bl.id], baseline: result, completionControls, interactiveControls } });
        return;
      }
      const both = await Promise.allSettled(modes.map(async (mode, index) => {
        if (index) await sleep(350);
        return lane(mode, isBuilding(mode) ? bl.id : standard.id);
      }));
      save(run, 'result.json', { model, capMs, lanes: both.map(value => value.status === 'fulfilled'
        ? value.value : { error: String(value.reason) }) });
    } catch (error) {
      clearInterval(timer);
      save(run, 'result.json', { error: String(error), model, capMs });
    }
  }, 250);
  ctx.on('dispose', () => clearInterval(timer));
}

