import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

// Contract prose remains in the existing owner files. Every line used by a
// rehearsal is read from the pinned fixture so it cannot drift from the quote.
const requirement = (base, file, line, exactClause) => {
  const source = readFileSync(new URL(file, base), 'utf8').split(/\r?\n/u)[line - 1];
  const quote = exactClause ?? source;
  assert.ok(source.includes(quote), file + ':' + line);
  assert.ok(quote && !quote.startsWith('#'), file + ':' + line);
  return { file, start: line, end: line, quote };
};
const example = (id, input, expectedJson, clause, diagnosticCases) => ({
  id, input, expectedJson, expectedExitCode: 0, requirement: clause,
  ...(diagnosticCases ? { diagnosticCases } : {}),
});
const contract = (id, examples) => ({ id, recipe: 'engineering-json', examples });
const ok = (actions = [], units = 0) => ({ status: 'ok', actions, units });
const error = error => ({ status: 'error', error, actions: [], units: 0 });
const change = (id, units = 1, depends_on = []) => ({ id, component: 'component', units, depends_on });
const request = (changes, overrides = {}) => ({ environment: 'staging', action: 'plan', budget: 5,
  changes, applied: [], ...overrides });

export function releaseRollbackDiagnostics(base) {
  const graph = [change('a-consumer', 1, ['b-prerequisite']), change('b-prerequisite'), change('z-independent')];
  const applied = graph.map(({ id }) => id);
  const clause = requirement(base, 'SPEC.md', 14, '`rollback` emits only applied changes, using the reverse of the full deterministic topological order.');
  return contract('public-rollback-order-diagnostics', [
    example('reverse-preserves-applied-prerequisite-edge', request(graph, { action: 'rollback', applied, budget: 0 }),
      ok(['z-independent', 'a-consumer', 'b-prerequisite'], 3), clause, ['rollback-order']),
    example('reverse-lexical-control-without-edge',
      request(graph.map(item => ({ ...item, depends_on: [] })), { action: 'rollback', applied, budget: 0 }),
      ok(['z-independent', 'b-prerequisite', 'a-consumer'], 3), clause),
  ]);
}

export function selectiveReleaseRollback(base, lockedScope = false) {
  const restored = requirement(base, 'SPEC.md', 14, 'Both environments support plan and rollback in G1.');
  const cap = requirement(base, 'CHANGE-G2.md', 6, 'For a staging plan, the effective budget is the smaller of the request budget and **3**. A quota violation is `budget-exceeded`, including when the request permits more.');
  const retain = requirement(base, 'CHANGE-G2.md', 7, 'Staging rollback accepts `retain`, default empty. It lists IDs that are already applied and must remain.');
  const item = change('rollback-item');
  return { heading: '回退顺序', ...(lockedScope ? { lockedScope: true } : {}), files: ['policy.py'], contracts: [contract('public-release-reopen-production', [
    example('restored-production-plan', request([item], { environment: 'production' }), ok([item.id], 1), restored),
    example('restored-production-rollback',
      request([item], { environment: 'production', action: 'rollback', applied: [item.id], budget: 0 }), ok([item.id], 1), restored),
    example('staging-plan-quota-preserved', request([change('quota-item', 4)], { budget: 9 }), error('budget-exceeded'), cap),
    example('staging-rollback-retention-preserved',
      request([item], { action: 'rollback', budget: 0, applied: [item.id], retain: [item.id] }), ok(), retain),
  ])] };
}

export function selectiveReservationRollback(base, lockedScope = false) {
  const oldShape = requirement(base, 'SPEC.md', 5, '未支持的 operation 或额外顶层字段返回 `invalid-request`。');
  const inspect = requirement(base, 'SPEC.md', 5, '成功 inspect 返回 `{"status":"ok","active":[...],"results":[]}`，按 resource、start、end、id 依次排序。');
  const transfer = requirement(base, 'CHANGE-G2.md', 5);
  const existing = { id: 'owner-rehearsal', resource: 'west', owner: 'ops', start: 0, end: 2, revision: 1 };
  const moved = { resource: 'east', owner: 'dispatch', start: 3, end: 5 };
  const transferEvent = { event_id: 'rehearsal-transfer', kind: 'transfer', id: existing.id, ...moved, if_revision: 1 };
  const applied = { operation: 'apply', active: [existing], events: [transferEvent] };
  const invalid = { status: 'error', error: 'invalid-request', eventIndex: null, active: [], results: [] };
  return { heading: '回退顺序', ...(lockedScope ? { lockedScope: true } : {}), files: ['ledger.py'], contracts: [contract('public-reservation-revert-closed-admission', [
    example('closed-field-rejected-again', { ...applied, closed: [] }, invalid, oldShape),
    example('transfer-still-supported', applied, { status: 'ok', active: [{ id: existing.id, ...moved, revision: 2 }],
      results: [{ event_id: transferEvent.event_id, outcome: 'applied', fromRevision: 1, toRevision: 2 }] }, transfer),
    example('inspect-preserved', { operation: 'inspect', active: [existing] },
      { status: 'ok', active: [existing], results: [] }, inspect),
  ])] };
}

