import assert from 'node:assert/strict';

const INPUT_EVENTS = new Map([['user-questions/request', 'question'], ['approval/request', 'approval']]);

// Mirror the native session wait contract. A pending question only ends this
// lane when all other stage agents have stopped working.
export function inputWait(gateway, agents, isIdle) {
  const pending = new Map();
  for (const { event, agentId } of gateway.getPendingRemoteEvents()) {
    const kind = INPUT_EVENTS.get(event);
    if (!kind) continue;
    const id = String(agentId);
    const kinds = pending.get(id) ?? new Set();
    kinds.add(kind);
    pending.set(id, kinds);
  }
  const waiting = agents.filter(agent => pending.has(String(agent.id)));
  if (!waiting.length || agents.some(agent => !pending.has(String(agent.id)) && !isIdle(agent))) return;
  return { agents: waiting, kinds: [...new Set(waiting.flatMap(agent => [...pending.get(String(agent.id))]))].sort() };
}

export function verifyInteractivePolicy() {
  const a = { id: 'a', idle: false }, b = { id: 'b', idle: false }, c = { id: 'c', idle: true };
  const question = { event: 'user-questions/request', agentId: 'a' };
  const approval = { event: 'approval/request', agentId: 'b' };
  const decide = (events, agents) => inputWait({ getPendingRemoteEvents: () => events }, agents, agent => agent.idle);
  assert.equal(decide([], [a]), undefined);
  assert.equal(decide([question], [b, c]), undefined);
  assert.equal(decide([question], [a, b]), undefined);
  assert.deepEqual(decide([question], [a, c]), { agents: [a], kinds: ['question'] });
  assert.deepEqual(decide([question, approval], [a, b, c]), { agents: [a, b], kinds: ['approval', 'question'] });
  assert.equal(decide([{ event: 'other/request', agentId: 'a' }], [a]), undefined);
  return { passed: 6, total: 6 };
}

