    missing field is reported as invalid-batch-item: it is a structural defect,
    unlike a present field's bad value, which reports its own code later.
    """
    if not isinstance(item, dict):
        raise JournalError("invalid-batch-item")
    present = keyed_fields(item)
    if present - BATCH_ITEM_FIELDS or BATCH_ITEM_FIELDS - present - OPTIONAL_ITEM_FIELDS:
        # An unknown field or an absent required one are both malformed.
        raise JournalError("invalid-batch-item")
    request = {"action": "rollback"}
    for field in BATCH_ITEM_FIELDS:
        request[field] = item[field] if field in present else []
    return request


