        # request the service must answer, and the decoder reports it as a
        # RuntimeError family member that ValueError does not cover, so without
        # this clause it would escape as a traceback and a nonzero exit.
        result = invalid_json()
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

