        raw_items, limit = read_envelope(envelope)
        limit = batch_limit(limit)
    except (JournalError, PolicyError) as exc:
        return batch_failure(str(exc), None)
    results = []
    # operation_id -> fingerprint of the first item that used it. An ID's first
    # occurrence owns its result; a later item either retries it or conflicts.
    seen = {}
    charged = 0
    for index, raw_item in enumerate(raw_items):
        try:
            operation_id, item = read_item(raw_item)
        except JournalError as exc:
            return batch_failure(str(exc), index)
        data = fingerprint(item)
        previous = seen.get(operation_id)
        if previous is None:
            try:
                # The item never names an action, so the batch supplies rollback.
                policy = decide(item["environment"], "rollback", item["budget"])
                actions, units = resolved(item, policy)
            except (PolicyError, JournalError) as exc:
                return batch_failure(str(exc), index)
            seen[operation_id] = data
            charged += units
            results.append({"actions": actions, "units": units,
                            "operationId": operation_id})
            continue
        if data != previous:
            # Same ID, different request data: the caller reused an identity
            # for a different operation, so the later item is the offender.
            return batch_failure("conflicting-operation", index)
        # A retry. Only the first item's result is returned, and it was charged
        # once, so a retry adds no result entry and no units of its own.
    if charged > limit:
        # The batch as a whole is over quota; no single item is at fault.
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": charged}

