                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(_read_dependencies(row)),
        }
        previous = unique.get(change["id"])
        if previous is None:
            unique[change["id"]] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return [unique[key] for key in sorted(unique)]


def read_applied(journal):
    """Validate the persisted release journal and return its unique change IDs."""
    return set(_id_list(journal, "invalid-change"))


def read_retain(request, applied):
    """Read the G2 rollback `retain` list: applied IDs that must remain installed.

    `retain` defaults to empty. Malformed lists are rejected here; an ID that is
    a valid string but was never applied is rejected here too, because that needs
    the persisted journal and no other module is allowed to own it. Repeated IDs
    are harmless; the value is consumed as a set.
    """
    retained = set(_id_list(request.get("retain", []), "invalid-retain"))
    if not retained <= applied:
        raise JournalError("invalid-retain")
    return retained


def keyed_fields(record):
    """String keys of a record; a non-string key can never name an allowed field."""
    return {key for key in record if isinstance(key, str)}


def read_operation_id(item):
    """Validate the G4 `operation_id`: a nonempty string of at most 64 characters.

    The value is compared verbatim, so nothing here normalizes it -- no case
    folding, no whitespace trimming. Only the type and the length are enforced.
    Characters are counted as code points.
    """
    operation_id = item.get("operation_id")
    if (not isinstance(operation_id, str) or not operation_id
            or len(operation_id) > OPERATION_ID_MAX_LENGTH):
        raise JournalError("invalid-batch-item")
    return operation_id


def fingerprint(request):
    """Canonical text of a bulk item's request data, for G4 retry equivalence.

    Two items with the same `operation_id` are a retry only when their complete
    request data matches. `operation_id` itself is excluded -- it is compared
    separately, and leaving it in would only restate that comparison. The rules
    the owner fixed:

    * object key order is irrelevant, so keys are sorted;
    * array order is preserved, so lists are walked in place;
    * a number and a boolean never match, even though Python compares 1 == True,
      because types are encoded, never coerced.

    Round-tripping through `json.dumps` gives a total, injective encoding: it
    distinguishes every JSON type, escapes strings exactly, and emits no
    whitespace, so equal JSON values always produce equal text.
    """
    return json.dumps(canonical(request), sort_keys=True)


def canonical(value):
    """Recursively re-shape `value` so equal JSON data encodes identically.

    Object keys are sorted and every scalar keeps its exact type. JSON object
    keys are always strings, so sorting them cannot compare mixed types.
    """
    if isinstance(value, dict):
        return {key: canonical(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [canonical(entry) for entry in value]
    return value


def _read_item(item):
    """Re-shape one bulk item into the single-rollback request the planner takes.

    Only the six item fields are legal, so a misplaced key -- including a
    per-item `action` -- cannot be silently ignored. The optional fields are
    supplied with their documented defaults (`applied` and `retain` are both []
    when absent) so a caller can omit them and still form a valid item. A
    missing field is reported as invalid-batch-item: it is a structural defect,
    unlike a present field's bad value, which reports its own code later.
    `operation_id` is validated here too, so all structural checks are settled
    before any item is judged for retry, conflict or business rules.
    """
    if not isinstance(item, dict):
        raise JournalError("invalid-batch-item")
    present = keyed_fields(item)
    if present - BATCH_ITEM_FIELDS or BATCH_ITEM_FIELDS - present - OPTIONAL_ITEM_FIELDS:
        # An unknown field or an absent required one are both malformed.
        raise JournalError("invalid-batch-item")
    request = {"action": "rollback"}
    for field in BATCH_ITEM_FIELDS:
        if field == "operation_id":
            continue
        request[field] = item[field] if field in present else []
    return request


def read_envelope(envelope):
    """Validate the bulk envelope and return (ordered requests, limit).

    G4 allows exactly `action`, `limit` and `requests`. A broken envelope has no
    item to point at, so every defect here reports invalid-batch (the planner
    answers with a null requestIndex) -- including a missing or malformed
    `limit`, which is not a per-item field.
    """
    if not isinstance(envelope, dict):
        raise JournalError("invalid-batch")
    if keyed_fields(envelope) != BATCH_ENVELOPE_FIELDS:
        raise JournalError("invalid-batch")
    if envelope["action"] != BATCH_ACTION:
        raise JournalError("invalid-batch")
    requests = envelope["requests"]
    if not isinstance(requests, list) or not MIN_BATCH <= len(requests) <= MAX_BATCH:
        raise JournalError("invalid-batch")
    return requests, envelope["limit"]


def read_item(item):
    """Shape-check one bulk item and return its operation ID plus request.

    Both halves of the structural pass travel together so the planner never has
    to re-derive one without the other.
    """
    operation_id = read_operation_id(item) if isinstance(item, dict) else None
    return operation_id, _read_item(item)


def read_batch(envelope):
    """Validate a whole bulk rollback and return its ordered item pairs."""
    requests, _ = read_envelope(envelope)
    return [read_item(item) for item in requests]

