"""Compose policy and journal data into a plan."""
import heapq

from journal import (JournalError, fingerprint, read_applied, read_changes,
                     read_envelope, read_item, read_retain)
from policy import (BATCH_ACTION, PolicyError, batch_limit, decide, limit_for)


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def batch_failure(code, index):
    return {"status": "error", "error": code, "requestIndex": index,
            "results": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. An unapplied dependency is not installed and so is never kept, but the
    walk continues through it: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it.

    The whole graph is traced to its roots; only the applied ancestors become
    part of the result. Every visited node is pushed once (an unapplied one is
    clearly not in `keep`), so a diamond or a long chain costs one pass per node.
    """
    keep = set(retained)
    visited = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in visited:
                continue
            visited.add(target)
            if target in applied:
                keep.add(target)
            stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def resolved(request, policy):
    """Validate one request and return (actions, units) in execution order, or raise.

    Shared by the single-request entry and every bulk item so the two can never
    drift: replay, deduplication, ordering, the staging plan quota and the G2
    rollback retention closure all live here once. Raises PolicyError for a
    request-level rejection and JournalError for a graph/journal one; neither
    ever leaves partial actions behind.
    """
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    if policy.action == "rollback":
        retained = read_retain(request, applied)
        actions = rollback_actions(by_id, order, applied, retained)
    else:
        actions = [key for key in order if key not in applied]
        if sum(by_id[key]["units"] for key in actions) > policy.limit:
            raise PolicyError("budget-exceeded")
    return actions, sum(by_id[key]["units"] for key in actions)


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    if request.get("action") == BATCH_ACTION or "requests" in request:
        # A `requests` list is batch shape whether or not its `action` is
        # spelled right. Letting it fall through to the single-request path
        # would report invalid-environment for what is really a broken
        # envelope, so any batch-shaped record is answered by the batch rules.
        return plan_batch(request)
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        actions, units = resolved(request, policy)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}


def plan_batch(envelope):
    """G4 bulk rollback: one ordered pass, retry-aware, all or nothing.

    The owner fixed the order of concerns, and it is deliberately not the same
    as G3's. G3 settled every item's structure before any business rule ran;
    G4 interleaves two layers but keeps each layer's precedence:

    1. The envelope is settled first (invalid-batch, null index): its three
       fields, the 1..128 request list and the `limit` type.
    2. In request order, each item's structure *and* its `operation_id` are
       checked first (invalid-batch-item, that item's index). So a malformed
       item is reported at its own position even when an earlier, well-formed
       item would have failed on its own business rules -- the same guarantee
       G3 gave, now decided on one left-to-right pass.
    3. An item whose structure is sound is then judged by its operation ID
       before any business rule: a repeat of an earlier ID with identical
       request data is a retry, which contributes no result entry and no units
       of its own -- the first item already answered it. A repeat with
       different data is `conflicting-operation` at the later item's index.
    4. Only a genuinely new ID runs the G2 validation and computation. A real
       failure here ends the batch with that item's own code and index.
    5. Only once every item has survived all of the above is the batch quota
       applied: the units of the de-duplicated rollback actions are compared
       with `limit`, so retries are never charged twice. Exceeding it is
       `batch-limit-exceeded` with a null index -- there is no offending item.

    Items share nothing: each gets its own changes, applied journal, retain set,
    graph and order, so an ID in one item neither exists nor is applied in
    another. Two different operation IDs stay independent even when their
    rollback parameters are identical; only the operation ID decides identity.
    """
    try:
        # A broken envelope has no item to point at, so its index is null.
        raw_items, limit = read_envelope(envelope)
        limit = batch_limit(limit)
    except (JournalError, PolicyError) as exc:
        return batch_failure(str(exc), None)
    results = []
    # operation_id -> fingerprint of the first item that used it. An ID's first
    # occurrence owns its result; a later item either retries it or conflicts.
    seen = {}
    charged = 0
    for index, raw_item in enumerate(raw_items):
        try:
            operation_id, item = read_item(raw_item)
        except JournalError as exc:
            return batch_failure(str(exc), index)
        data = fingerprint(item)
        previous = seen.get(operation_id)
        if previous is None:
            try:
                # The item never names an action, so the batch supplies rollback.
                policy = decide(item["environment"], "rollback", item["budget"])
                actions, units = resolved(item, policy)
            except (PolicyError, JournalError) as exc:
                return batch_failure(str(exc), index)
            seen[operation_id] = data
            charged += units
            results.append({"actions": actions, "units": units,
                            "operationId": operation_id})
            continue
        if data != previous:
            # Same ID, different request data: the caller reused an identity
            # for a different operation, so the later item is the offender.
            return batch_failure("conflicting-operation", index)
        # A retry. Only the first item's result is returned, and it was charged
        # once, so a retry adds no result entry and no units of its own.
    if charged > limit:
        # The batch as a whole is over quota; no single item is at fault.
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": charged}

