"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def invalid_json():
    return {"status": "error", "error": "invalid-json", "actions": [], "units": 0}


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = invalid_json()
    except RecursionError:
        # Pathologically nested JSON exhausts the decoder's stack. It is still a
        # request the service must answer, and the decoder reports it as a
        # RuntimeError family member that ValueError does not cover, so without
        # this clause it would escape as a traceback and a nonzero exit.
        result = invalid_json()
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

