"""Compose policy and journal data into a plan."""
import heapq

from journal import (
    BATCH_ACTION,
    JournalError,
    read_applied,
    read_batch,
    read_batch_item,
    read_changes,
    read_retain,
    request_identity,
)
from policy import PolicyError, limit_for, read_batch_limit


class BudgetExceeded(Exception):
    """The plan's emitted units exceed the effective staging plan ceiling."""

    def __str__(self):
        return "budget-exceeded"


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def batch_failure(code, index):
    """G3/G4 failure shape: the whole batch fails at one index (None for the envelope)."""
    return {"status": "error", "error": code, "requestIndex": index, "results": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. The walk follows the complete graph and only the applied nodes it reaches
    become kept: an unapplied dependency is not installed, so it is never kept,
    but the walk continues through it. c -> b(unapplied) -> a still keeps a when c
    is retained, because a is installed and c still needs it, even when b itself
    is not applied.
    """
    keep = set(retained)
    seen = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in applied:
                keep.add(target)
            if target not in seen:
                seen.add(target)
                stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def evaluate(request):
    """Run the G1/G2 pipeline and return (actions, units).

    Raises PolicyError, JournalError or BudgetExceeded instead of emitting a
    partial result, so callers decide the response shape.
    """
    # The environment/action/budget check comes first so a frozen production
    # request is reported before any graph or change validation runs.
    policy = limit_for(request)
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    if policy.action == "rollback":
        retained = read_retain(request, applied)
        actions = rollback_actions(by_id, order, applied, retained)
    else:
        actions = [key for key in order if key not in applied]
        if sum(by_id[key]["units"] for key in actions) > policy.limit:
            raise BudgetExceeded()
    return actions, sum(by_id[key]["units"] for key in actions)


def rollback_many(request):
    """G3/G4: run ordered, independent G2 rollback requests and report the first failure.

    G4 keeps every G3 rule -- items are independent, an element's `action` is set
    here, budget is validated but never caps a rollback, the earliest failing item
    ends the whole batch with its own error code, and no partial results are
    returned -- and adds a deduplicated batch with a batch-wide limit. Phases, in
    this order:

    1. Envelope. A bad top-level shape or `limit` fails with a null index.
    2. Structure and operation IDs for every item, in request order.
    3. Duplicate/conflict, in request order. The first item for an `operation_id`
       defines it; a later item with the same ID and identical request data is
       only a retry of that first item and is not evaluated again, while a later
       item with the same ID and different data raises conflicting-operation at
       that later item's index. The conflict outranks any per-item domain error.
    4. G2 per item, in request order, but only for first occurrences; retries
       repeat the stored result and are not charged.
    5. Batch quota, only after every item above succeeded: the deduplicated units
       must be less than or equal to `limit`.

    An item's business errors therefore come before the batch quota, and the quota
    comes before any success. Everything that reaches the caller is all-or-nothing.
    """
    try:
        items = read_batch(request)
        limit = read_batch_limit(request)
    except (JournalError, PolicyError) as exc:
        return batch_failure(str(exc), None)

    identities = []
    for item in items:
        try:
            identities.append((read_batch_item(item), request_identity(item)))
        except (JournalError, TypeError):
            return batch_failure("invalid-batch-item", len(identities))

    seen = {}
    for index, (operation_id, identity) in enumerate(identities):
        if operation_id in seen:
            if seen[operation_id] != identity:
                return batch_failure("conflicting-operation", index)
        else:
            seen[operation_id] = identity
    # First occurrence per operation ID. Written as an explicit loop: in a mapping
    # comprehension the value expression is evaluated before the loop variable,
    # so the tuple probe as written would bind the last index to every ID.
    first_index = {}
    for index, (operation_id, _) in enumerate(identities):
        first_index.setdefault(operation_id, index)

    results = {}
    pending = None
    try:
        for pending, index in first_index.items():
            operation = dict(items[index], action="rollback")
            operation.pop("operation_id", None)
            actions, units = evaluate(operation)
            results[pending] = {"actions": actions, "units": units, "operationId": pending}
    except (PolicyError, JournalError, BudgetExceeded) as exc:
        # `pending` names the item being evaluated, i.e. the first occurrence of
        # its operation ID; a retry later in the batch never changes this index.
        return batch_failure(str(exc), first_index[pending])

    total = sum(row["units"] for row in results.values())
    if limit is not None and total > limit:
        return batch_failure("batch-limit-exceeded", None)
    return {
        "status": "ok",
        "results": [results[operation_id] for operation_id, _ in identities],
        "units": sum(results[operation_id]["units"] for operation_id in first_index),
    }


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    if request.get("action") == BATCH_ACTION:
        return rollback_many(request)
    try:
        actions, units = evaluate(request)
    except (PolicyError, JournalError, BudgetExceeded) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

