(including G4 retry deduplication) and result assembly, so the batch can never
drift from the single-request business rules.
"""
import heapq
import json

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for


# G3: the batch is bounded so one request cannot ask the process to hold an
# unbounded number of independent plans in memory.
MAX_BATCH_REQUESTS = 128
# G4: `limit` is now a required top-level field (no default), so a G3-shaped
# batch that lacks it is rejected as invalid-batch rather than silently uncapped.
BATCH_TOP_LEVEL_FIELDS = {"action", "limit", "requests"}
BATCH_REQUEST_FIELDS = {"environment", "budget", "changes", "applied", "retain", "operation_id"}
# G4: operation_id is required on every batch item and compared verbatim, so a
# 64-character ceiling keeps the identity key small and the comparison exact.
MAX_OPERATION_ID_LENGTH = 64


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. An unapplied dependency is not installed and so is never kept, but the
    walk must still pass through it: c -> b(unapplied) -> a still keeps a when c
    is retained, because a is installed and c still needs it. Stopping at b
    would uninstall a under a change that remains. `seen` is separate from
    `keep` so traversal does not depend on what is kept, and the single
    iterative pass stays O(V+E) without recursion on 2,000+ change graphs.
    """
    keep = set(retained)
    seen = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in seen:
                continue
            seen.add(target)
            if target in applied:
                keep.add(target)
            stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def batch_failure(code, request_index):
    """All-or-nothing batch failure: no partial results survive.

    `request_index` is the failing item's position, or None when the batch as a
    whole is at fault (invalid-batch, batch-limit-exceeded). Every batch error
    keeps this one shape so callers never see partial `results`.
    """
    return {
        "status": "error",
        "error": code,
        "requestIndex": request_index,
        "results": [],
        "units": 0,
    }


def batch_item_request(item, index):
    """Validate one batch element's shape and turn it into a single rollback request.

    Only the outer shape is judged here: a mapping with no field outside the
    documented set, plus the G4 `operation_id` requirement (a nonempty string of
    at most MAX_OPERATION_ID_LENGTH characters). Whether the other documented
    fields are present is left to `plan`, which already owns every default
    (`applied`, `retain`) and the per-field error codes, so an item missing an
    optional field is still a valid rollback.
    The action is forced to rollback because the batch entry point owns that
    choice and an element may not override it. `operation_id` is dropped from
    the derived request: it is batch identity, and the single-request path must
    never learn about it.
    """

    if not isinstance(item, dict) or any(key not in BATCH_REQUEST_FIELDS for key in item):
        raise JournalError("invalid-batch-item")
    operation_id = item.get("operation_id")
    if (not isinstance(operation_id, str) or not operation_id
            or len(operation_id) > MAX_OPERATION_ID_LENGTH):
        raise JournalError("invalid-batch-item")
    request = {key: value for key, value in item.items() if key != "operation_id"}
    request["action"] = "rollback"
    return request


def request_identity(request):
    """Canonical form of one item's request data, used only for retry equality.

    G4 equality ignores object key order but preserves array order, and JSON
    numbers and booleans must not be conflated (``1`` is not ``true``).
    `sort_keys` handles key order and list order survives untouched. Python's
    own equality would already separate ``1``/``True``/``"1"``, but neither it
    nor the default JSON encoding tags the JSON types, so the ambiguous scalars
    are re-tagged here and `json.dumps` with `allow_nan=False` gives one stable
    string; hashing that string avoids O(n^2) comparisons across the batch.
    """

    def tag(value):
        if isinstance(value, bool):
            return ["bool", value]
        if isinstance(value, (int, float)):
            return ["number", value]
        if isinstance(value, str):
            return ["string", value]
        if value is None:
            return ["null"]
        if isinstance(value, list):
            return ["array", [tag(entry) for entry in value]]
        if isinstance(value, dict):
            # Key order is irrelevant, but two keys that JSON keeps distinct
            # (e.g. 1 and "1") must not collapse into one object key.
            return ["object", sorted([[tag(key), tag(item)] for key, item in value.items()],
                                     key=lambda pair: json.dumps(pair[0], sort_keys=True,
                                                                 allow_nan=False))]
        return ["other", repr(value)]

    return json.dumps(tag(request), sort_keys=True, allow_nan=False,
                      separators=(",", ":"))


def plan_batch(request):
    """Process a `rollback-many` batch in order, stopping at the first failing item.

    G4 fixes the precedence, and it is the reason this is two passes rather than
    one: all item shapes and operation IDs are judged before any retry/conflict
    decision, and every item's G2 business result is computed before the batch
    `limit` is compared. A real per-item error therefore always beats
    `batch-limit-exceeded`, and the quota can never mask a malformed item.
    """

    if any(key not in BATCH_TOP_LEVEL_FIELDS for key in request):
        return batch_failure("invalid-batch", None)
    limit = request.get("limit")
    # type() rather than isinstance() so a boolean limit is never accepted.
    if type(limit) is not int or limit < 0:
        return batch_failure("invalid-batch", None)
    items = request.get("requests")
    if not isinstance(items, list) or not 1 <= len(items) <= MAX_BATCH_REQUESTS:
        return batch_failure("invalid-batch", None)

    prepared = []
    for index, item in enumerate(items):
        try:
            single = batch_item_request(item, index)
        except JournalError:
            return batch_failure("invalid-batch-item", index)
        prepared.append((index, item["operation_id"], single))

    # Pass two: identity first, execution second, in original request order.
