    choice and an element may not override it. `operation_id` is dropped from
    the derived request: it is batch identity, and the single-request path must
    never learn about it.
    """

    if not isinstance(item, dict) or any(key not in BATCH_REQUEST_FIELDS for key in item):
        raise JournalError("invalid-batch-item")
    operation_id = item.get("operation_id")
    if (not isinstance(operation_id, str) or not operation_id
            or len(operation_id) > MAX_OPERATION_ID_LENGTH):
        raise JournalError("invalid-batch-item")
