    numbers and booleans must not be conflated (``1`` is not ``true``).
    `sort_keys` handles key order and list order survives untouched. Python's
    own equality would already separate ``1``/``True``/``"1"``, but neither it
    nor the default JSON encoding tags the JSON types, so the ambiguous scalars
    are re-tagged here and `json.dumps` with `allow_nan=False` gives one stable
    string; hashing that string avoids O(n^2) comparisons across the batch.
    """

    def tag(value):
        if isinstance(value, bool):
            return ["bool", value]
        if isinstance(value, (int, float)):
            return ["number", value]
        if isinstance(value, str):
            return ["string", value]
        if value is None:
            return ["null"]
        if isinstance(value, list):
            return ["array", [tag(entry) for entry in value]]
        if isinstance(value, dict):
            # Key order is irrelevant, but two keys that JSON keeps distinct
            # (e.g. 1 and "1") must not collapse into one object key.
            return ["object", sorted([[tag(key), tag(item)] for key, item in value.items()],
                                     key=lambda pair: json.dumps(pair[0], sort_keys=True,
                                                                 allow_nan=False))]
        return ["other", repr(value)]

    return json.dumps(tag(request), sort_keys=True, allow_nan=False,
                      separators=(",", ":"))


