    # Pass two: identity first, execution second, in original request order.
    # `first` holds the canonical data per operation_id so a later item with the
    # same ID is either an exact retry or a conflict. A retry contributes no new
    # result and no units: G4 returns only the first attempt's result, so
    # `results` has one entry per distinct operation in first-appearance order.
    first = {}
    results = []
    total = 0
    for index, operation_id, single in prepared:
        identity = request_identity(single)
        seen = first.get(operation_id)
        if seen is not None:
            # Same operation_id: identical data is a retry, so the earlier
            # result stands and the units are not charged again. Different data
            # is a conflict reported at this later position.
            if seen[0] != identity:
                return batch_failure("conflicting-operation", index)
            continue
