        # Shape first: a malformed element fails here even when its
        # operation_id happens to collide with an earlier, valid one.
        try:
            single = batch_item_request(item, index)
        except JournalError:
            return batch_failure("invalid-batch-item", index)
        operation_id = item["operation_id"]
        identity = request_identity(single)
        seen = first.get(operation_id)
        if seen is not None:
            # Same operation_id: identical data is a retry, so the earlier
            # result stands and the units are not charged again. Different data
            # is a conflict reported at this later position.
            if seen[0] != identity:
                return batch_failure("conflicting-operation", index)
            continue
